            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if not alive:
        return float(min(budget, 18.0))

    if hp <= 2 or no_water >= 2:
        emergency = max(92.0, highest_prev + 4.0, avg_prev + 8.0)
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        strong = max(68.0, highest_prev * 0.78 + 3.0)
        return float(min(budget, strong))

    if slots >= 2:
        if highest_prev >= 120:
            bid = 24.0
        elif highest_prev >= 90:
            bid = 31.0
        else:
            bid = 36.0
        if urgent_opp >= 2:
            bid += 6.0
        return float(min(budget, bid))

    bid = 48.0
    if highest_prev >= 120:
        bid = 58.0
    elif highest_prev >= 90:
        bid = 64.0
    elif highest_prev >= 60:
        bid = 61.0
    else:
        bid = 56.0

    if urgent_opp >= 2:
        bid += 7.0
    elif urgent_opp == 1:
        bid += 3.0

    if rich_opp >= 2 and hp >= 6:
        bid -= 6.0

