    elif hp >= 4:
        reserve_cap = min(budget, 0.82 * budget)

    return float(min(reserve_cap, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids for immediate pressure signal
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bidv = float(bid)
                prev_bids.append(bidv)
                prev_by_id[oid] = bidv
            except Exception:
                pass

    # Estimate how aggressive the field was yesterday
    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0

    # Supply-based urgency: with supply near 15, water is scarcer; still water requirement is 9
    # Use a scarcity factor to slightly increase bids when supply is low.
    scarcity = 1.0
    if supply <= 16.0:
        scarcity = 1.15
    elif supply <= 19.0:
        scarcity = 1.08
    elif supply >= 22.0:
        scarcity = 0.95

    # Health urgency: if we've already gone without water, increase bid.
    # If hp is low, prioritize survival over savings.
    hp_urgency = 1.0
    if hp <= 2.0:
        hp_urgency = 1.35
    elif hp <= 4.0:
        hp_urgency = 1.18

    no_water_urgency = 1.0
    if no_water_days >= 2:
        no_water_urgency = 1.25
    elif no_water_days == 1:
        no_water_urgency = 1.10

    # Field targeting: Cindy likely overbids (survived 10 days with very high avg bid).
    # We'll aim to beat the low/mid bidders without matching Cindy's extremes.
    target = None
    if prev_bids:
        # If someone was bidding extremely high yesterday, don't chase exactly.
        # Instead bid around the median of yesterday bids, nudged upward.
        sorted_b = sorted(prev_bids)
        mid = sorted_b[len(sorted_b)//2]
        # If highest was extreme, cap our target below highest.
        if highest_prev >= DAILY_SALARY * 1.4:
            target = max(mid, lowest_prev + 5.0)
            target = min(target, highest_prev * 0.65)
        else:
            target = mid
    else:
        target = DAILY_SALARY * 0.55

    # Convert target into a bid with urgency multipliers and scarcity.
    base_bid = float(target)
    bid = base_bid * scarcity * hp_urgency * no_water_urgency

    # Also ensure we can afford it and avoid overspending early.
    # Budget includes remaining; cap by a fraction depending on day.
    day_factor = 1.0
    if day <= 3:
        day_factor = 0.85
    elif day >= 8:
        day_factor = 1.05

    max_affordable = max(0.0, budget)
    bid = min(bid * day_factor, max_affordable)

    # Hard safety bounds: never bid negative; if very low budget, bid what we can.
    if bid <= 0.0:
        return 0.0

    # If we are in immediate danger, push higher.
    if hp <= 2.0 or no_water_days >= 2:
        bid = min(max_affordable, max(bid, DAILY_SALARY * 0.85 * scarcity))

    # If we are doing fine, keep bids moderate.
    if hp >= 6.0 and no_water_days == 0:
        bid = min(max_affordable, min(bid, DAILY_SALARY * 0.6 * scarcity))

    return float(bid)

